<?php
require_once 'includes/functions.php'; require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ids=$_POST['product_id']??[];$qtys=$_POST['quantity']??[];$pdo=db();try{$pdo->beginTransaction();$items=[];$total=0;foreach($ids as $i=>$id){$id=(int)$id;$qty=(int)($qtys[$i]??0);if($id<1||$qty<1)continue;$q=$pdo->prepare('SELECT id,name,price,quantity FROM products WHERE id=? FOR UPDATE');$q->execute([$id]);$p=$q->fetch();if(!$p||$p['quantity']<$qty)throw new RuntimeException('Insufficient stock for '.($p['name']??'selected product'));$line=$p['price']*$qty;$items[]=['id'=>$id,'name'=>$p['name'],'price'=>$p['price'],'qty'=>$qty,'line'=>$line];$total+=$line;}if(!$items)throw new RuntimeException('Add at least one product.');$q=$pdo->prepare('INSERT INTO sales(user_id,total_amount,payment_method) VALUES(?,?,?)');$q->execute([$_SESSION['user']['id'],$total,$_POST['payment_method']??'Cash']);$saleId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,price,quantity,line_total) VALUES(?,?,?,?,?,?)');$upd=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=?');foreach($items as $it){$ins->execute([$saleId,$it['id'],$it['name'],$it['price'],$it['qty'],$it['line']]);$upd->execute([$it['qty'],$it['id']]);}$pdo->commit();redirect('receipt.php?id='.$saleId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');redirect('sale.php');}}
$products=db()->query('SELECT id,name,price,quantity FROM products WHERE quantity>0 ORDER BY name')->fetchAll();$page_title='New Sale';require 'includes/header.php'; ?>
<div class="panel"><h1>New Sale / Checkout</h1><p class="muted">Select products and quantities. Stock is reduced after a successful sale.</p><form method="post" id="sale-form"><?= csrf_field() ?><div id="sale-lines"><div class="sale-line"><select name="product_id[]" required><option value="">Choose product</option><?php foreach($products as $p): ?><option value="<?= (int)$p['id'] ?>" data-price="<?= e($p['price']) ?>" data-stock="<?= (int)$p['quantity'] ?>"><?= e($p['name']) ?> — <?= money($p['price']) ?> (Stock: <?= (int)$p['quantity'] ?>)</option><?php endforeach; ?></select><input type="number" name="quantity[]" min="1" value="1" required><button type="button" class="button danger remove-line">Remove</button></div></div><button type="button" class="button secondary" id="add-line">+ Add another item</button><label class="payment">Payment method<select name="payment_method"><option>Cash</option><option>Card</option><option>UPI</option></select></label><div class="total-box">Estimated total: <strong id="total">₹0.00</strong></div><button class="button">Complete sale &amp; generate receipt</button></form></div>
<script>
const lines=document.getElementById('sale-lines');function updateTotal(){let sum=0;lines.querySelectorAll('.sale-line').forEach(row=>{const opt=row.querySelector('select').selectedOptions[0];const qty=Number(row.querySelector('input').value)||0;if(opt&&opt.dataset.price)sum+=Number(opt.dataset.price)*qty;});document.getElementById('total').textContent=new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(sum);}
document.getElementById('add-line').addEventListener('click',()=>{const row=lines.querySelector('.sale-line').cloneNode(true);row.querySelector('select').selectedIndex=0;row.querySelector('input').value=1;lines.appendChild(row);updateTotal();});lines.addEventListener('input',updateTotal);lines.addEventListener('change',updateTotal);lines.addEventListener('click',e=>{if(e.target.classList.contains('remove-line')){if(lines.querySelectorAll('.sale-line').length>1)e.target.closest('.sale-line').remove();updateTotal();}});updateTotal();
</script>
<?php require 'includes/footer.php'; ?>
